$eid=(int)($_SESSION['etablissement_id']??0);$cfg=hostStructureConfig($pdo,$eid);if(!hostStructureEnabled($cfg,'DEPARTEMENT')){http_response_code(404);exit('Ce niveau a été retiré.');}
$singular=hostStructureLabel($cfg,'DEPARTEMENT',false,'Département');$plural=hostStructureLabel($cfg,'DEPARTEMENT',true,'Départements');$canManage=hasPermission($pdo,'host.manage');$pageTitle=$plural;$activePage='hospital-departments';require_once __DIR__.'/../../includes/app-header.php';
