<style>.host-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.host-kpi,.host-card{background:#fff;border:1px solid #e7ebf0;border-radius:14px}.host-kpi{padding:16px}.host-kpi small{display:block;color:#64748b;font-size:11px;text-transform:uppercase}.host-kpi strong{display:block;font-size:27px;margin-top:4px}.host-card{overflow:hidden}@media(max-width:900px){.host-kpis{grid-template-columns:repeat(2,1fr)}}</style>
<main class="dashboard-content"><div class="stagia-page-head"><div><h1><?=htmlspecialchars($plural)?></h1><p>Premier niveau de la structure d’accueil.</p></div><?php if($canManage): ?><button class="btn btn-primary-stagia" id="addBtn"><i class="bi bi-plus-lg me-1"></i>Ajouter <?=htmlspecialchars($singular)?></button><?php endif; ?></div>
<div class="host-kpis mb-4"><div class="host-kpi"><small>Total</small><strong id="kTotal">0</strong></div><div class="host-kpi"><small>Actifs</small><strong id="kActive">0</strong></div><div class="host-kpi"><small>Services</small><strong id="kServices">0</strong></div><div class="host-kpi"><small>Unités</small><strong id="kUnits">0</strong></div></div>
<div class="host-card"><div class="p-3 border-bottom"><div class="row g-2"><div class="col-md-8"><input id="search" class="form-control" placeholder="Rechercher..."></div><div class="col-md-4"><select id="status" class="form-select"><option value="">Tous les statuts</option><option value="1">Actifs</option><option value="0">Inactifs</option></select></div></div></div><div class="table-responsive"><table class="table stagia-modern-table align-middle mb-0"><thead><tr><th>CODE</th><th><?=htmlspecialchars(mb_strtoupper($singular))?></th><th class="text-center">ENFANTS</th><th>STATUT</th><th>CRÉÉ LE</th><th class="text-end">ACTION</th></tr></thead><tbody id="rows"><tr><td colspan="6" class="text-center py-5 text-muted">Chargement...</td></tr></tbody></table></div></div></main>
<?php if($canManage): ?><div class="modal fade" id="itemModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="form"><div class="modal-header"><div><h5 class="modal-title" id="modalTitle">Ajouter <?=htmlspecialchars($singular)?></h5><small class="text-muted">Le code est généré automatiquement.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf'])?>"><input type="hidden" name="id" id="itemId"><input type="hidden" name="type" value="DEPARTEMENT"><input type="hidden" name="has_parent" value="0"><div class="mb-3"><label class="form-label">Nom *</label><input name="nom" id="name" class="form-control" maxlength="150" required></div><div><label class="form-label">Description</label><textarea name="description" id="description" class="form-control" rows="3"></textarea></div></div><div class="modal-footer"><button type="button" class="btn btn-light border" data-bs-dismiss="modal">Annuler</button><button type="submit" class="btn btn-primary-stagia" id="saveBtn"><i class="bi bi-check-lg me-1"></i>Enregistrer</button></div></form></div></div></div><?php endif; ?>
<script>document.addEventListener('DOMContentLoaded',()=>{const BASE_URL='<?=BASE_URL?>',$=id=>document.getElementById(id),esc=STAGIA.escape,canManage=<?=$canManage?'true':'false'?>,SINGULAR=<?=json_encode($singular,JSON_UNESCAPED_UNICODE)?>;let items=[],timer;const modal=canManage?new bootstrap.Modal($('itemModal')):null;async function load(){const q=new URLSearchParams({type:'DEPARTEMENT'});if($('search').value.trim())q.set('search',$('search').value.trim());if($('status').value!=='')q.set('actif',$('status').value);try{const r=await STAGIA.request(BASE_URL+'/actions/espace-hopital/structure-list.php?'+q),d=r.data;items=d.items||[];$('kTotal').textContent=d.kpi.departments||0;$('kActive').textContent=items.filter(x=>Number(x.actif)===1).length;$('kServices').textContent=d.kpi.services||0;$('kUnits').textContent=d.kpi.units||0;$('rows').innerHTML=items.length?items.map(x=>`<tr><td><strong>${esc(x.code)}</strong></td><td><strong>${esc(x.nom)}</strong>${x.description?`<small class="d-block text-muted">${esc(x.description)}</small>`:''}</td><td class="text-center"><span class="badge bg-light text-dark border">${Number(x.children_count)||0}</span></td><td>${Number(x.actif)===1?'<span class="badge bg-success-subtle text-success">Actif</span>':'<span class="badge bg-secondary-subtle text-secondary">Inactif</span>'}</td><td>${esc(x.date_creation||'—')}</td><td class="text-end">${canManage?`<button class="btn btn-sm btn-outline-primary edit" data-id="${x.id}"><i class="bi bi-pencil"></i></button> <button class="btn btn-sm btn-outline-secondary toggle" data-id="${x.id}" data-next="${Number(x.actif)===1?0:1}"><i class="bi bi-${Number(x.actif)===1?'pause-circle':'play-circle'}"></i></button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="text-center py-5 text-muted">Aucun élément.</td></tr>';document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>edit(Number(b.dataset.id)));document.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>toggle(Number(b.dataset.id),Number(b.dataset.next)))}catch(e){$('rows').innerHTML=`<tr><td colspan="6" class="text-center py-5 text-danger">${esc(e.message)}</td></tr>`}}if(canManage){$('addBtn').onclick=()=>{$('form').reset();$('itemId').value='';$('modalTitle').textContent='Ajouter '+SINGULAR;modal.show()};function edit(id){const x=items.find(v=>Number(v.id)===id);if(!x)return;$('form').reset();$('itemId').value=x.id;$('name').value=x.nom||'';$('description').value=x.description||'';$('modalTitle').textContent='Modifier '+SINGULAR;modal.show()}$('form').onsubmit=async e=>{e.preventDefault();STAGIA.loading($('saveBtn'),true);try{const r=await STAGIA.post(BASE_URL+'/actions/espace-hopital/structure-save.php',new FormData(e.currentTarget));STAGIA.toast(r.message);modal.hide();await load()}catch(e){STAGIA.toast(e.message,'danger')}finally{STAGIA.loading($('saveBtn'),false)}};async function toggle(id,next){if(!STAGIA.confirm(next?'Réactiver cet élément ?':'Désactiver cet élément ?'))return;const fd=new FormData();fd.append('csrf','<?=$_SESSION['csrf']?>');fd.append('id',id);fd.append('actif',String(next));try{const r=await STAGIA.post(BASE_URL+'/actions/espace-hopital/structure-status.php',fd);STAGIA.toast(r.message);await load()}catch(e){STAGIA.toast(e.message,'danger')}}}$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(load,300)};$('status').onchange=load;load()});</script>
